import cocotb
from cocotb.clock import Clock
from cocotb.triggers import FallingEdge, RisingEdge, Timer
from random import Random


SIGN = 0x80000000
FRAC = 0x007FFFFF
INF = 0x7F800000
QNAN = 0x7FC00001
MAX_FINITE = 0x7F7FFFFF
MIN_NORMAL = 0x00800000


def classify(x):
    exponent = (x >> 23) & 255
    fraction = x & FRAC
    if exponent == 255:
        if fraction == 0:
            return "inf"
        if fraction & 0x400000:
            return "qnan"
        return "snan"
    if exponent == 0:
        if fraction == 0:
            return "zero"
        return "subnormal"
    return "normal"


def finite_ratio(x):
    exponent = (x >> 23) & 255
    fraction = x & FRAC
    if exponent == 0:
        significand = fraction
        power = -149
    else:
        significand = (1 << 23) | fraction
        power = exponent - 150

    if power >= 0:
        return significand << power, 1
    return significand, 1 << (-power)


def floor_log2_ratio(n, d):
    e = n.bit_length() - d.bit_length()
    if e >= 0:
        if n < (d << e):
            e -= 1
    else:
        if (n << (-e)) < d:
            e -= 1
    return e


def rounded_integer(n, d, scale, mode, sign):
    # Round (n / d) / 2**scale to an integer.
    if scale >= 0:
        divisor = d << scale
        dividend = n
    else:
        divisor = d
        dividend = n << (-scale)

    q, remainder = divmod(dividend, divisor)
    increment = False
    if remainder:
        if mode == 0:
            twice = remainder << 1
            increment = twice > divisor or (twice == divisor and (q & 1) != 0)
        elif mode == 2:
            increment = sign == 0
        elif mode == 3:
            increment = sign == 1

    if increment:
        q += 1
    return q, remainder != 0


def round_finite(n, d, sign, mode):
    # First round to 24 significant bits with an unbounded exponent.
    e = floor_log2_ratio(n, d)
    uq, unused = rounded_integer(n, d, e - 23, mode, sign)
    unbounded_e = e
    if uq >= (1 << 24):
        uq >>= 1
        unbounded_e += 1

    overflow = unbounded_e > 127
    if overflow:
        to_inf = mode == 0 or (mode == 2 and sign == 0) or (
            mode == 3 and sign == 1
        )
        magnitude = INF if to_inf else MAX_FINITE
        return magnitude, 1, 1

    if e >= -126:
        q, inexact = rounded_integer(n, d, e - 23, mode, sign)
        if q >= (1 << 24):
            q >>= 1
            e += 1
        magnitude = ((e + 127) << 23) | (q - (1 << 23))
    else:
        q, inexact = rounded_integer(n, d, -149, mode, sign)
        magnitude = q

    return magnitude, int(inexact), 0


def reference(op, mode, a, b):
    if op >= 4:
        return None

    ca = classify(a)
    cb = classify(b)
    sa = (a >> 31) & 1
    sb = (b >> 31) & 1

    # The specification excludes both-infinity operations entirely.
    if ca == "inf" and cb == "inf":
        return None

    expected = {
        "inf": 0,
        "snan": int(ca == "snan" or cb == "snan"),
        "qnan": 0,
        "ine": 0,
        "overflow": 0,
        "underflow": 0,
        "zero": 0,
        "div_by_zero": 0,
    }

    def finish(bits, mask=0xFFFFFFFF):
        expected["out"] = (bits, mask)
        return expected

    nan_a = ca == "qnan" or ca == "snan"
    nan_b = cb == "qnan" or cb == "snan"
    if nan_a or nan_b:
        expected["qnan"] = 1
        if nan_a and nan_b:
            return finish(QNAN, 0x7FFFFFFF)
        nan_sign = sa if nan_a else sb
        return finish(QNAN | (nan_sign << 31))

    if op == 3 and ca == "subnormal":
        # These flags are unspecified for a subnormal dividend.
        expected.pop("ine")
        expected.pop("underflow")

    if op == 0 or op == 1:
        effective_sb = sb ^ int(op == 1)
