from random import Random


SIGN = 0x80000000
FRAC = 0x007FFFFF
EXP = 0x7F800000
MIN_NORMAL = 0x00800000
MAX_FINITE = 0x7F7FFFFF


def is_nan(x):
    return (x & EXP) == EXP and (x & FRAC) != 0


def is_snan(x):
    return is_nan(x) and (x & 0x00400000) == 0


def is_inf(x):
    return (x & 0x7FFFFFFF) == EXP


def is_zero(x):
    return (x & 0x7FFFFFFF) == 0


def is_subnormal(x):
    return (x & EXP) == 0 and (x & FRAC) != 0


def finite_units(x):
    """Signed finite value in units of 2**-149."""
    exponent = (x >> 23) & 255
    fraction = x & FRAC
    if exponent == 0:
        magnitude = fraction
    else:
        magnitude = ((1 << 23) | fraction) << (exponent - 1)
    return -magnitude if x & SIGN else magnitude


def floor_log2_ratio(n, d):
    e = n.bit_length() - d.bit_length()
    if e >= 0:
        if n < (d << e):
            e -= 1
    elif (n << -e) < d:
        e -= 1
    return e


def quantize(n, d, step, sign, mode):
    """Round n/d to an integer multiple of 2**step."""
    if step >= 0:
        denominator = d << step
        numerator = n
    else:
        numerator = n << -step
        denominator = d
    q, rem = divmod(numerator, denominator)
    increment = False
    if rem:
        if mode == 0:
            twice = rem << 1
            increment = twice > denominator or (
                twice == denominator and (q & 1) != 0
            )
        elif mode == 2:
            increment = sign == 0
        elif mode == 3:
            increment = sign == 1
    if increment:
        q += 1
    return q, rem != 0


def rounded_finite(n, d, sign, mode):
    """Return binary32 bits, inexact, and overflow for nonzero n/d."""
    e = floor_log2_ratio(n, d)

    # Overflow is determined after rounding to 24 bits with an unbounded
    # exponent, not simply by comparing the exact value with MAX_FINITE.
    unbounded_step = e - 23
    uq, unused = quantize(n, d, unbounded_step, sign, mode)
    if unbounded_step >= 104:
        overflow = (uq << (unbounded_step - 104)) > ((1 << 24) - 1)
    else:
        overflow = uq > (((1 << 24) - 1) << (104 - unbounded_step))

    if overflow:
        away = mode == 0 or (mode == 2 and sign == 0) or (
            mode == 3 and sign == 1
        )
        magnitude = EXP if away else MAX_FINITE
        return (sign << 31) | magnitude, 1, 1

    if e < -126:
        q, inexact = quantize(n, d, -149, sign, mode)
        magnitude = q
    else:
        q, inexact = quantize(n, d, e - 23, sign, mode)
        if q == (1 << 24):
            q >>= 1
            e += 1
        magnitude = ((e + 127) << 23) | (q - (1 << 23))

    return (sign << 31) | magnitude, int(inexact), 0


