    # Flag order: inf, snan, qnan, ine, overflow, underflow, zero, div_by_zero.
    if op >= 4 or (is_inf(a) and is_inf(b)):
        return None

    flags = [0, int(is_snan(a) or is_snan(b)), 0, 0, 0, 0, 0, 0]
    if op == 3 and is_subnormal(a):
