import cocotb
from cocotb.triggers import Timer
from random import Random


def classify(bits):
    exponent = (bits >> 23) & 255
    fraction = bits & 0x7FFFFF
    if exponent == 255:
        if fraction == 0:
            return "inf"
        if fraction & 0x400000:
            return "qnan"
        return "snan"
    if exponent == 0:
        return "zero" if fraction == 0 else "sub"
    return "normal"


def finite_parts(bits):
    exponent = (bits >> 23) & 255
    fraction = bits & 0x7FFFFF
    if exponent == 0:
        return fraction, -149
    return (1 << 23) | fraction, exponent - 150


def round_increment(quotient, remainder, denominator, mode, sign):
    if remainder == 0:
        return 0
    if mode == 0:
        twice = remainder * 2
        return int(twice > denominator or
                   (twice == denominator and (quotient & 1) != 0))
    if mode == 1:
        return 0
    if mode == 2:
        return int(sign == 0)
    return int(sign == 1)


def scaled_division(numerator, denominator, shift):
    if shift >= 0:
        numerator <<= shift
    else:
        denominator <<= -shift
    quotient, remainder = divmod(numerator, denominator)
    return quotient, remainder, denominator


def rounded_finite(numerator, denominator, sign, mode):
    """Round a positive, nonzero rational to binary32."""
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    else:
        if (numerator << -exponent) < denominator:
            exponent -= 1

    tiny = (numerator << 126) < denominator

    if exponent >= -126:
        q, rem, den = scaled_division(numerator, denominator, 23 - exponent)
        q += round_increment(q, rem, den, mode, sign)
        if q == (1 << 24):
            q >>= 1
            exponent += 1
        if exponent > 127:
            infinity = mode == 0 or (mode == 2 and sign == 0) or (
                mode == 3 and sign == 1
            )
            magnitude = 0x7F800000 if infinity else 0x7F7FFFFF
            return (sign << 31) | magnitude, 1, 1, tiny
        magnitude = ((exponent + 127) << 23) | (q - (1 << 23))
        return (sign << 31) | magnitude, int(rem != 0), 0, tiny

    q, rem, den = scaled_division(numerator, denominator, 149)
    q += round_increment(q, rem, den, mode, sign)
    return (sign << 31) | q, int(rem != 0), 0, tiny


