        return ("nan", sign, 0, 1, (fraction & 0x400000) == 0)

    if exponent == 0:
        if fraction == 0:
            return ("zero", sign, 0, 1, False)
        return ("finite", sign, fraction, 1 << 149, False)

    mantissa = (1 << 23) | fraction
    power = exponent - 150
    if power >= 0:
        return ("finite", sign, mantissa << power, 1, False)
    return ("finite", sign, mantissa, 1 << (-power), False)


